export default function nextMessage({ events, previousState }) {
  if (!Array.isArray(events) || events.length > 50) throw Error("Invalid Gmail poll");
  if (
    events.some((x) => !x || typeof x.messageId !== "string" || !x.messageId) ||
    new Set(events.map((x) => x.messageId)).size !== events.length
  )
    throw Error("Invalid or repeated message ID");
  let index = previousState === null ? 0 : previousState.index + 1;
  if (!Number.isInteger(index) || index < 0 || index > events.length)
    throw Error("Invalid progress");
  return {
    state: { index },
    more: index < events.length,
    messageId: index < events.length ? events[index].messageId : "",
  };
}

