export default function nextAttachment({
  expectedId,
  messageId,
  sender,
  attachmentList,
  payload,
  previousState,
  folderId,
}) {
  if (messageId !== expectedId || !Array.isArray(attachmentList))
    throw Error("Unexpected Gmail message");
  if (typeof folderId !== "string" || !folderId.trim() || folderId === "YOUR_DRIVE_FOLDER_ID")
    throw Error("Configure Drive folder ID");
  let index = previousState?.messageId === messageId ? previousState.index + 1 : 0;
  if (!Number.isInteger(index) || index < 0 || index > attachmentList.length)
    throw Error("Invalid attachment progress");
  const more = index < attachmentList.length,
    part = more ? attachmentList[index] : null;
  let name = "-",
    mimeType = "application/octet-stream",
    attachmentId = "",
    size = 0,
    inline = "";
  if (more) {
    if (
      !part ||
      typeof part.filename !== "string" ||
      !Number.isSafeInteger(part.size) ||
      part.size < 0 ||
      part.size > 52428800
    )
      throw Error("Invalid attachment metadata");
    const filename = part.filename || "attachment";
    name = filename;
    mimeType = part.mimeType || mimeType;
    size = part.size;
    attachmentId = part.attachmentId || "";
    if (!attachmentId) {
      let matches = [];
      const walk = (p) => {
        if (!p || typeof p !== "object") return;
        if (p.partId === part.partId && typeof p.body?.data === "string") matches.push(p.body.data);
        for (const x of p.parts || []) walk(x);
      };
      if (part.partId === null) throw Error("Inline attachment missing part ID");
      walk(payload);
      if (matches.length !== 1) throw Error("Inline attachment data is missing or ambiguous");
      inline = matches[0];
    }
  }
  return {
    state: { messageId, index },
    more,
    remote: !!attachmentId,
    attachmentId,
    filename: part?.filename || "attachment",
    mimeType,
    size,
    inline,
    name,
    parents: [folderId],
  };
}

