export default async function f(
  { raw, text, messageId, fileState, filename, acknowledge, resolution },
  ctx,
) {
  let x;
  try {
    x = JSON.parse(
      String(text ?? "")
        .trim()
        .replace(/^```(?:json)?\s*|\s*```$/g, ""),
    );
  } catch {
    throw Error("Invalid classification");
  }
  if (raw?.candidates?.[0]?.finishReason !== "STOP" || typeof x.match !== "boolean")
    throw Error("Incomplete PDF classification");
  const key = "gmail-pdf:" + messageId + ":" + fileState.index,
    s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending PDF upload " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, upload: false };
    }
  }
  if (s?.status === "done" || !x.match) return { key, upload: false };
  await ctx.state.set(key, { status: "pending", filename });
  return { key, upload: true };
}
